BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
create function pg_temp.draft()returns jsonb language sql as $$select'{"organization":{"name":"Organization onboarding SQL fixture","type":"owner_operator","legalName":"Retained legal name"},"profile":{"name":"Organization onboarding property SQL fixture","propertyType":null,"address":{"street":"","city":"City without street","state":"","zip":""},"websiteUrl":"https://example.invalid/property","additionalUrls":["https://example.invalid/policy"],"unitCount":0,"yearBuilt":null,"amenities":[],"specialFeatures":[],"brandVoice":"","targetAudience":""},"contacts":[{"id":"ee570000-0000-4000-8000-000000000051","type":"primary","name":"Private contact","email":"private@example.test","phone":"","role":"","billingAddress":{"street":"","city":"Billing city","state":"","zip":""},"billingMethod":"","specialInstructions":"Retain private instructions","needsW9":true,"isPrimary":true}],"connectionRequests":[{"platform":"google_ads","accountId":"planned-reference","accountName":"Planned account","notes":"Review access later"}],"step":"review"}'::jsonb$$;
create function pg_temp.save_input(rev int default 0,draft jsonb default null)returns jsonb language sql as $$select jsonb_build_object('operation','save','expectedRevision',rev,'draft',coalesce(draft,pg_temp.draft()),'reason','Save exact first-time setup draft')$$;
create function pg_temp.complete_input()returns jsonb language sql as $$select jsonb_build_object('operation','complete','expectedRevision',q.revision,'draftHash',public.knowledge_hash(q.draft),'confirmed',true,'reason','Review complete first organization setup')from public.organization_setups q where actor_id='11111111-1111-1111-1111-111111111111'$$;
create function pg_temp.decide(i uuid,input jsonb)returns jsonb language sql as $$select public.decide_organization_setup(i,'11111111-1111-1111-1111-111111111111',input)$$;
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111')->'alreadyMember'='true','existing member receives read-only guidance');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.save_input())->>'state'='already_member','existing member cannot create another organization');
insert into st values('profile',(select to_jsonb(p)from public.profiles p where id='11111111-1111-1111-1111-111111111111'));
update public.profiles set org_id=null,role=null where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111')->'setup'='null','new account has no invented draft');
select pg_temp.check_it(public.read_organization_setup(gen_random_uuid())->>'state'='forbidden','unknown account cannot read setup');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000010',pg_temp.save_input())->>'state'='saved','first private draft saved');
select pg_temp.check_it((select org_id is null from public.profiles where id='11111111-1111-1111-1111-111111111111')and not exists(select 1 from public.organizations where name='Organization onboarding SQL fixture'),'draft does not create membership or organization');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000010',pg_temp.save_input())->>'state'='replayed','lost draft reply recovers same decision');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000010',pg_temp.save_input(1))->>'state'='request_conflict','changed request identity rejected');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.save_input())->>'state'='setup_changed','stale draft revision rejected');
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111','{"decisionId":"ee570000-0000-4000-8000-000000000010"}')->'decision'->'after_state'->'draft'=pg_temp.draft(),'exact saved draft readable after reload');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000010',jsonb_build_object('operation','cancel_unused','inputHash',repeat('a',64),'reason','Cancel only unused setup'))->>'state'='replayed','cancel recovers an existing decision without undo');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000099',jsonb_build_object('operation','cancel_unused','inputHash',repeat('a',64),'reason','Cancel only unused setup'))->'cancelled'='true','unused identity cancellation retained');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000099',pg_temp.save_input(1))->>'state'='decision_cancelled','delayed cancelled draft cannot save');
-- A failed draft history save must not advance the current draft.
create function pg_temp.fail_draft()returns trigger language plpgsql as $$begin raise exception 'Synthetic draft history failure';end$$;
create trigger fixture_draft_failure before insert on public.organization_setup_decisions for each row execute function pg_temp.fail_draft();
do $$begin begin perform pg_temp.decide(gen_random_uuid(),pg_temp.save_input(1));raise exception 'Expected rollback'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic draft history failure'then raise;end if;perform pg_temp.check_it(true,'draft history failure reaches transaction boundary');end;end$$;
drop trigger fixture_draft_failure on public.organization_setup_decisions;
select pg_temp.check_it((select revision=1 from public.organization_setups where actor_id='11111111-1111-1111-1111-111111111111'),'failed history cannot change saved draft');
insert into st values('complete',pg_temp.complete_input());
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v||jsonb_build_object('draftHash',repeat('a',64))from st where k='complete'))->>'state'='setup_changed','completion requires exact saved draft');
do $$begin begin perform pg_temp.decide(gen_random_uuid(),pg_temp.complete_input()||'{"confirmed":false}');raise exception 'Expected confirmation'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'completion requires explicit confirmation');end;end$$;
-- Failure in any downstream local step rolls back the new org, member binding and first property.
create function pg_temp.fail_task()returns trigger language plpgsql as $$begin if exists(select 1 from public.properties where id=new.property_id and name='Organization onboarding property SQL fixture')then raise exception 'Synthetic onboarding task failure';end if;return new;end$$;
create trigger fixture_org_task_failure before insert on public.onboarding_tasks for each row execute function pg_temp.fail_task();
do $$begin begin perform pg_temp.decide('ee570000-0000-4000-8000-000000000020',pg_temp.complete_input());raise exception 'Expected rollback'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic onboarding task failure'then raise;end if;perform pg_temp.check_it(true,'task failure reaches atomic completion boundary');end;end$$;
drop trigger fixture_org_task_failure on public.onboarding_tasks;
select pg_temp.check_it((select org_id is null from public.profiles where id='11111111-1111-1111-1111-111111111111')and not exists(select 1 from public.organizations where name='Organization onboarding SQL fixture')and not exists(select 1 from public.properties where name='Organization onboarding property SQL fixture'),'task failure leaves no partially created org or membership');
create function pg_temp.fail_org_action()returns trigger language plpgsql as $$begin if new.action='organization.setup.completed'then raise exception 'Synthetic organization action failure';end if;return new;end$$;
create trigger fixture_org_action_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_org_action();
do $$begin begin perform pg_temp.decide('ee570000-0000-4000-8000-000000000020',pg_temp.complete_input());raise exception 'Expected rollback'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic organization action failure'then raise;end if;perform pg_temp.check_it(true,'completion event failure reaches atomic boundary');end;end$$;
drop trigger fixture_org_action_failure on public.shared_action_events;
select pg_temp.check_it((select org_id is null from public.profiles where id='11111111-1111-1111-1111-111111111111')and not exists(select 1 from public.organizations where name='Organization onboarding SQL fixture')and(select state='draft'and revision=1 from public.organization_setups where actor_id='11111111-1111-1111-1111-111111111111'),'event failure rolls back all setup and retains recoverable draft');
-- A malformed native draft cannot become a partial property through completion.
select pg_temp.decide(gen_random_uuid(),pg_temp.save_input(1,jsonb_set(pg_temp.draft(),'{contacts}','[]')));
do $$begin begin perform pg_temp.decide(gen_random_uuid(),pg_temp.complete_input());raise exception 'Expected contact review'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'A primary contact is required to complete setup'then raise;end if;perform pg_temp.check_it(true,'native contact validation runs before completion commits');end;end$$;
select pg_temp.check_it(not exists(select 1 from public.organizations where name='Organization onboarding SQL fixture'),'invalid completion leaves no partial org');
select pg_temp.decide(gen_random_uuid(),pg_temp.save_input(2));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v from st where k='complete'))->>'state'='setup_changed','completion against a superseded draft held');
update st set v=pg_temp.complete_input()where k='complete';
insert into st values('completed',pg_temp.decide('ee570000-0000-4000-8000-000000000020',(select v from st where k='complete')));
select pg_temp.check_it(v->>'state'='saved'and v->'completed'='true','exact completion saved')from st where k='completed';
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000020',(select v from st where k='complete'))->>'state'='replayed','lost completion reply recovers after membership changes');
select pg_temp.check_it((select count(*)from public.organizations where name='Organization onboarding SQL fixture')=1 and(select count(*)from public.properties where name='Organization onboarding property SQL fixture')=1,'completion replay does not duplicate org or property');
select pg_temp.check_it((select p.org_id=q.org_id and p.role='admin'from public.profiles p join public.organization_setups q on q.actor_id=p.id where p.id='11111111-1111-1111-1111-111111111111'),'membership points to completed organization');
select pg_temp.check_it((select settings->>'legalName'='Retained legal name'and settings->>'organizationType'='owner_operator'from public.organizations where id=(select(v->>'organizationId')::uuid from st where k='completed')),'organization metadata retained');
select pg_temp.check_it((select unit_count=0 and year_built is null and address->>'city'='City without street'and not(settings?'timezone')and onboarding_completed_at is not null from public.properties where id=(select(v->>'propertyId')::uuid from st where k='completed')),'zero unknown city-only address and explicit completion preserved without guessed timezone');
select pg_temp.check_it((select count(*)from public.property_contacts where property_id=(select(v->>'propertyId')::uuid from st where k='completed'))=1 and(select needs_w9 and billing_address->>'city'='Billing city'and special_instructions='Retain private instructions'from public.property_contacts where id='ee570000-0000-4000-8000-000000000051'),'exact primary contact and billing details retained');
select pg_temp.check_it((select count(*)from public.onboarding_tasks where property_id=(select(v->>'propertyId')::uuid from st where k='completed'))=9,'default checklist created exactly once');
select pg_temp.check_it((select connection_requests=pg_temp.draft()->'connectionRequests'from public.property_setup_state where property_id=(select(v->>'propertyId')::uuid from st where k='completed'))and not exists(select 1 from public.integration_credentials where property_id=(select(v->>'propertyId')::uuid from st where k='completed')),'plans saved without activating credentials');
select pg_temp.check_it(not exists(select 1 from public.knowledge_sources where property_id=(select(v->>'propertyId')::uuid from st where k='completed'))and not exists(select 1 from public.documents where property_id=(select(v->>'propertyId')::uuid from st where k='completed')),'setup invents no published knowledge or fetch results');
select pg_temp.check_it((select count(*)from public.shared_action_events where property_id=(select(v->>'propertyId')::uuid from st where k='completed')and action in('property.created','property.onboarding.completed','organization.setup.completed'))=3,'all completion effects linked to exact actions');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id=(select(v->>'propertyId')::uuid from st where k='completed')and(training_eligible or(request::text||result::text)like'%private@example.test%'or(request::text||result::text)like'%Retained legal name%')),'shared activity excludes private inputs and training eligibility');
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111')->'setup'->>'state'='completed','completed setup receipt remains readable');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.save_input(4))->>'state'='already_completed','new save cannot silently replace completed setup');
update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111')->>'state'='forbidden','account transfer hides old private setup evidence');
select pg_temp.check_it(pg_temp.decide('ee570000-0000-4000-8000-000000000020',(select v from st where k='complete'))->>'state'='forbidden','account transfer blocks old completion replay');
update public.profiles set org_id=(select(v->>'organizationId')::uuid from st where k='completed')where id='11111111-1111-1111-1111-111111111111';
select set_config('p11.organization_setup_actor','',true);
do $$begin begin update public.organization_setups set draft='{}'where actor_id='11111111-1111-1111-1111-111111111111';raise exception 'Expected guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'direct setup mutation blocked');end;begin update public.organization_setup_decisions set input='{}'where id='ee570000-0000-4000-8000-000000000010';raise exception 'Expected history guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'native draft history immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.organization_setups','select')and not has_function_privilege('anon','public.decide_organization_setup(uuid,uuid,jsonb)','execute'),'private drafts closed to direct client access');
insert into st values('history',public.read_organization_setup('11111111-1111-1111-1111-111111111111'));
insert into public.organization_setup_decisions(id,setup_id,actor_id,kind,input,input_hash,after_state,result)select gen_random_uuid(),q.id,q.actor_id,'save','{"reason":"Historical native draft fixture"}','fixture','{}','{}'from public.organization_setups q cross join generate_series(1,1001)where q.actor_id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111')->>'total'='1005','full native history exceeds REST cap');
select pg_temp.check_it(jsonb_array_length(public.read_organization_setup('11111111-1111-1111-1111-111111111111','{"offset":1000}')->'items')=5,'oldest draft history remains reachable');
select pg_temp.check_it(public.read_organization_setup('11111111-1111-1111-1111-111111111111',jsonb_build_object('offset',20,'expectedHash',(select v->>'historyHash'from st where k='history')))->>'state'='history_changed','changed history cannot silently skip versions');
select n as passed_assertions from assertion_count;
ROLLBACK;
